{"command":"python3 - << 'PY'
import subprocess, itertools
def run(args, inp):
    p=subprocess.run(["./executable"]+args, input=inp.encode(), capture_output=True)
    return p.returncode, p.stdout.decode(), p.stderr.decode()
inputs={'y':"a: 1\n",'t':"a=1\n",'j':'{"a":1}\n','c':"a=1\n"}
outputs={'y':"a: 1\n",'t':"a = 1\n",'j':'{"a":1}\n','c':'"a" = 1'}
def model(seq):
    fm=[]
    for ch in seq:
        if ch=='r': fm+=['j','y']
        else: fm.append(ch)
    if not fm: return ('y','j')
    if len(fm)==1: return (fm[0],'j')
    return (fm[-2], fm[-1])

def detect(seq):
    args=[f'-{seq}'] if seq else []
    rc,out,err=run(args,'{\n')
    if 'parsing YAML' in err: inp='y'
    elif 'parsing TOML' in err: inp='t'
    elif 'parsing JSON' in err: inp='j'
    elif 'parsing HCL' in err: inp='c'
    elif rc==0: inp='c'
    else: return ('?','?')
    rc2,out2,err2=run(args, inputs[inp])
    # map output
    rev={v:k for k,v in outputs.items()}
    out = rev.get(out2,'?'+out2)
    return (inp,out)

bad=0; total=0
for length in range(0,5):
    for seq in itertools.product('ytjcr', repeat=length):
        s=''.join(seq); total+=1
        m=model(s); d=detect(s)
        if m!=d:
            print("MISMATCH",s,m,d); bad+=1
print(total,"bad",bad)
PY
"}

