cat > order/order.go <<'EOF'
package order

// MapItem is a single ordered key/value pair.
type MapItem struct {
	Key string
	Val interface{}
}

// MapSlice preserves the order in which keys were encountered.
type MapSlice []MapItem
EOF
cat > main.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

type format int

const (
	formatYAML format = iota
	formatTOML
	formatJSON
	formatHCL
)

func (f format) name() string {
	switch f {
	case formatYAML:
		return "YAML"
	case formatTOML:
		return "TOML"
	case formatJSON:
		return "JSON"
	case formatHCL:
		return "HCL"
	}
	return ""
}

type options struct {
	in, out    format
	noNum      bool
	escapeHTML bool
	indent     bool
	parseKeys  bool
	help       bool
	version    bool
}

const version = "v0.0.0"

func usageString(prog string) string {
	return fmt.Sprintf(`Usage: %s [-][ytjcrneikhv]

Convert between YAML, TOML, JSON, and HCL.
Preserves map order.

-x[x]  Convert using stdin. Valid options:
          -yj, -y = YAML to JSON (default)
          -yy     = YAML to YAML
          -yt     = YAML to TOML
          -yc     = YAML to HCL
          -tj, -t = TOML to JSON
          -ty     = TOML to YAML
          -tt     = TOML to TOML
          -tc     = TOML to HCL
          -jj     = JSON to JSON
          -jy, -r = JSON to YAML
          -jt     = JSON to TOML
          -jc     = JSON to HCL
          -cy     = HCL to YAML
          -ct     = HCL to TOML
          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version

`, prog)
}

func parseFlags(args []string) (options, string) {
	var o options
	var formats []format
	var invalid []string
	appendFormat := func(f format) { formats = append(formats, f) }
	for _, arg := range args {
