package main

import (
	"app/order"
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"strconv"
	"strings"
	"time"
)

func writeJSON(v interface{}, opts options) ([]byte, error) {
	b := marshalJSONValue(v, opts.escapeHTML, opts.indent)
	return append(b, '\n'), nil
}

func marshalJSONValue(v interface{}, escapeHTML, indent bool) []byte {
	var buf bytes.Buffer
	writeJSONValue(&buf, v, escapeHTML, indent, 0)
	return buf.Bytes()
}

func jsonQuote(s string, escapeHTML bool) string {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(escapeHTML)
	_ = enc.Encode(s)
	return strings.TrimSuffix(buf.String(), "\n")
}

func jsonFloat(f float64) string {
	if math.IsNaN(f) {
		return "null"
	}
	if math.IsInf(f, 1) {
		f = math.MaxFloat64
	} else if math.IsInf(f, -1) {
		f = -math.MaxFloat64
	}
	b, err := json.Marshal(f)
	if err != nil {
		return "null"
	}
	return string(b)
}

func writeJSONValue(buf *bytes.Buffer, v interface{}, escapeHTML, indent bool, level int) {
	switch x := v.(type) {
	case nil:
		buf.WriteString("null")
	case bool:
		if x {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case string:
		buf.WriteString(jsonQuote(x, escapeHTML))
	case []byte:
		buf.WriteString(jsonQuote(string(x), escapeHTML))
	case int:
		buf.WriteString(strconv.FormatInt(int64(x), 10))
	case int8:
		buf.WriteString(strconv.FormatInt(int64(x), 10))
	case int16:
		buf.WriteString(strconv.FormatInt(int64(x), 10))
	case int32:
		buf.WriteString(strconv.FormatInt(int64(x), 10))
	case int64:
		buf.WriteString(strconv.FormatInt(x, 10))
	case uint:
		buf.WriteString(strconv.FormatUint(uint64(x), 10))
	case uint8:
		buf.WriteString(strconv.FormatUint(uint64(x), 10))
	case uint16:
		buf.WriteString(strconv.FormatUint(uint64(x), 10))
	case uint32:
		buf.WriteString(strconv.FormatUint(uint64(x), 10))
	case uint64:
		buf.WriteString(strconv.FormatUint(x, 10))
	case float32:
		buf.WriteString(jsonFloat(float64(x)))
	case float64:
		buf.WriteString(jsonFloat(x))
	case time.Time:
		b, err := json.Marshal(x)
		if err != nil {
			buf.WriteString(jsonQuote(x.String(), escapeHTML))
		} else {
			// json.Marshal on a string-ish value escapes HTML by default,
			// but timestamps never contain <>&.
			buf.Write(b)
		}
	case order.MapSlice:
		if len(x) == 0 {
			buf.WriteString("{}")
			return
		}
		buf.WriteByte('{')
		for i, it := range x {
			if i > 0 {
				buf.WriteByte(',')
			}
			if indent {
				buf.WriteByte('\n')
				buf.WriteString(strings.Repeat("  ", level+1))
			}
			buf.WriteString(jsonQuote(it.Key, escapeHTML))
			buf.WriteByte(':')
			if indent {
				buf.WriteByte(' ')
			}
			writeJSONValue(buf, it.Val, escapeHTML, indent, level+1)
		}
		if indent {
			buf.WriteByte('\n')
			buf.WriteString(strings.Repeat("  ", level))
		}
		buf.WriteByte('}')
	case []interface{}:
		if len(x) == 0 {
			buf.WriteString("[]")
			return
		}
		buf.WriteByte('[')
		for i, e := range x {
			if i > 0 {
				buf.WriteByte(',')
			}
			if indent {
				buf.WriteByte('\n')
				buf.WriteString(strings.Repeat("  ", level+1))
			}
			writeJSONValue(buf, e, escapeHTML, indent, level+1)
		}
		if indent {
			buf.WriteByte('\n')
			buf.WriteString(strings.Repeat("  ", level))
		}
		buf.WriteByte(']')
	default:
		b, err := json.Marshal(x)
		if err != nil {
			buf.WriteString(jsonQuote(fmt.Sprint(x), escapeHTML))
		} else {
			buf.Write(b)
		}
	}
}
