{"command":"cat > yamlconv.go <<'EOF'
package main

import (
	"app/order"
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"time"

	"gopkg.in/yaml.v3"
)

func parseYAML(data []byte, noNum bool) (interface{}, bool, error) {
	dec := yaml.NewDecoder(bytes.NewReader(data))
	var node yaml.Node
	err := dec.Decode(&node)
	if err != nil {
		if errors.Is(err, io.EOF) {
			return nil, true, nil
		}
		return nil, false, err
	}
	if node.Kind == 0 {
		return nil, true, nil
	}
	p := &yamlConvert{noNum: noNum, active: map[*yaml.Node]bool{}}
	v, err := p.convert(&node)
	if err != nil {
		return nil, false, err
	}
	return v, false, nil
}

func parseJSON(data []byte, noNum bool) (interface{}, error) {
	var raw json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, err
	}
	dec := yaml.NewDecoder(bytes.NewReader(data))
	var node yaml.Node
	if err := dec.Decode(&node); err != nil {
		return nil, err
	}
	p := &yamlConvert{noNum: noNum, active: map[*yaml.Node]bool{}}
	return p.convert(&node)
}

// parseJSONKey parses a string as JSON (used by the YAML -k flag).
func parseJSONKey(s string, noNum bool) (interface{}, error) {
	return parseJSON([]byte(s), noNum)
}

type yamlConvert struct {
	noNum  bool
	active map[*yaml.Node]bool
}

func (p *yamlConvert) convert(n *yaml.Node) (interface{}, error) {
	if n == nil {
		return nil, nil
	}
	switch n.Kind {
	case yaml.DocumentNode:
		if len(n.Content) == 0 {
			return nil, nil
		}
		return p.convert(n.Content[0])
	case yaml.AliasNode:
		if n.Alias == nil {
			return nil, nil
		}
		if p.active[n.Alias] {
			return nil, fmt.Errorf("anchor '%s' value contains itself", n.Value)
		}
		return p.convert(n.Alias)
	case yaml.ScalarNode:
		var v interface{}
		if err := n.Decode(&v); err != nil {
			return nil, fmt.Errorf("scalar decode error: %s", err.Error())
		}
		return v, nil
	case yaml.SequenceNode:
		if p.active[n] {
			return nil, fmt.Errorf("anchor '%s' value contains itself", n.Anchor)
		}
		p.active[n] = true
		defer delete(p.active, n)
		out := make([]interface{}, 0, len(n.Content))
		for _, c := range n.Content {
			v, err := p.convert(c)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
		return out, nil
	case yaml.MappingNode:
		if p.active[n] {
			return nil, fmt.Errorf("anchor '%s' value contains itself", n.Anchor)
		}
		p.active[n] = true
		defer delete(p.active, n)
		var result order.MapSlice
		for i := 0; i+1 < len(n.Content); i += 2 {
			kn, vn := n.Content[i], n.Content[i+1]
			if isMergeKey(kn) {
				merged, err := p.convertMergeValue(vn)
				if err != nil {
					return nil, err
				}
				for _, item := range merged {
					// Delete any existing entries with this key, then append.
					filtered := result[:0]
					// Build a new slice to avoid aliasing surprises.
					var kept order.MapSlice
					for _, existing := range result {
						if existing.Key != item.Key {
							kept = append(kept, existing)
						}
					}
					_ = filtered
					result = kept
					result = append(result, item)
				}
				continue
			}
			keyVal, err := p.convert(kn)
			if err != nil {
				return nil, err
			}
			keyStr := yamlKeyToString(keyVal, p.noNum)
			val, err := p.convert(vn)
			if err != nil {
				return nil, err
			}
			result = append(result, order.MapItem{Key: keyStr, Val: val})
		}
		if result == nil {
			result = order.MapSlice{}
		}
		return result, nil
	default:
		var v interface{}
		if err := n.Decode(&v); err != nil {
			return nil, err
		}
		return v, nil
	}
}

func isMergeKey(n *yaml.Node) bool {
	if n == nil {
		return false
	}
	if n.Kind == yaml.AliasNode && n.Alias != nil {
		return n.Alias.Tag == "!!merge"
	}
	return n.Tag == "!!merge"
}

func (p *yamlConvert) convertMergeValue(n *yaml.Node) (order.MapSlice, error) {
	target := n
	for target != nil && target.Kind == yaml.AliasNode {
		if p.active[target.Alias] {
			return nil, fmt.Errorf("anchor '%s' value contains itself", target.Value)
		}
		target = target.Alias
	}
	if target == nil || target.Kind != yaml.MappingNode {
		return nil, errors.New("map merge requires map or sequence of maps as the value")
	}
	v, err := p.convert(target)
	if err != nil {
		return nil, err
	}
	ms, ok := v.(order.MapSlice)
	if !ok {
		return nil, errors.New("map merge requires map or sequence of maps as the value")
	}
	return ms, nil
}

func yamlKeyToString(v interface{}, noNum bool) string {
	switch k := v.(type) {
	case string:
		return k
	case time.Time:
		return k.String()
	}
	tv := v
	if !noNum {
		tv = floatsToStrings(v)
		if s, ok := tv.(string); ok {
			return s
		}
	}
	return string(marshalJSONValue(tv, false, false))
}

// ----- YAML writing -----

type yamlWriter struct {
	parseKeys bool
	noNum     bool
}

var errNilYAMLKey = errors.New("reflect: call of reflect.Value.Set on zero Value")

func writeYAML(v interface{}, opts options) ([]byte, error) {
	w := &yamlWriter{parseKeys: opts.parseKeys, noNum: opts.noNum}
	node, err := w.toNode(v)
	if err != nil {
		return nil, err
	}
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(node); err != nil {
		_ = enc.Close()
		return nil, err
	}
	if err := enc.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func (w *yamlWriter) toNode(v interface{}) (*yaml.Node, error) {
	switch x := v.(type) {
	case order.MapSlice:
		n := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
		for _, item := range x {
			kn, err := w.keyNode(item.Key)
			if err != nil {
				return nil, err
			}
			vn, err := w.toNode(item.Val)
			if err != nil {
				return nil, err
			}
			n.Content = append(n.Content, kn, vn)
		}
		return n, nil
	case []interface{}:
		n := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, e := range x {
			cn, err := w.toNode(e)
			if err != nil {
				return nil, err
			}
			n.Content = append(n.Content, cn)
		}
		return n, nil
	default:
		var n yaml.Node
		if err := n.Encode(v); err != nil {
			return nil, err
		}
		return &n, nil
	}
}

func (w *yamlWriter) keyNode(key string) (*yaml.Node, error) {
	var kv interface{} = key
	if w.parseKeys {
		if parsed, err := parseJSONKey(key, w.noNum); err == nil {
			kv = parsed
		}
	}
	if kv == nil {
		return nil, errNilYAMLKey
	}
	if !w.noNum {
		kv = stringsToFloatsKey(kv)
	}
	if kv == nil {
		return nil, errNilYAMLKey
	}
	return w.toNode(kv)
}
EOF
"}

