		if len(n.Content) == 0 {
			return nil, nil
		}
		return p.convert(n.Content[0])
	case yaml.AliasNode:
		if n.Alias == nil {
			return nil, nil
		}
		if p.active[n.Alias] {
			return nil, fmt.Errorf("anchor '%s' value contains itself", n.Value)
		}
		return p.convert(n.Alias)
	case yaml.ScalarNode:
		var v interface{}
		if err := n.Decode(&v); err != nil {
			return nil, fmt.Errorf("scalar decode error: %s", err.Error())
		}
		return v, nil
	case yaml.SequenceNode:
		if p.active[n] {
			return nil, fmt.Errorf("anchor '%s' value contains itself", n.Anchor)
		}
		p.active[n] = true
		defer delete(p.active, n)
		out := make([]interface{}, 0, len(n.Content))
		for _, c := range n.Content {
			v, err := p.convert(c)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
		return out, nil
	case yaml.MappingNode:
		if p.active[n] {
			return nil, fmt.Errorf("anchor '%s' value contains itself", n.Anchor)
		}
		p.active[n] = true
		defer delete(p.active, n)
		var result order.MapSlice
		for i := 0; i+1 < len(n.Content); i += 2 {
			kn, vn := n.Content[i], n.Content[i+1]
			if isMergeKey(kn) {
				merged, err := p.convertMergeValue(vn)
				if err != nil {
					return nil, err
				}
				for _, item := range merged {
					// Delete any existing entries with this key, then append.
					filtered := result[:0]
					// Build a new slice to avoid aliasing surprises.
					var kept order.MapSlice
					for _, existing := range result {
						if existing.Key != item.Key {
							kept = append(kept, existing)
						}
					}
					_ = filtered
					result = kept
					result = append(result, item)
				}
				continue
			}
			keyVal, err := p.convert(kn)
			if err != nil {
				return nil, err
			}
			keyStr := yamlKeyToString(keyVal, p.noNum)
			val, err := p.convert(vn)
			if err != nil {
				return nil, err
			}
			result = append(result, order.MapItem{Key: keyStr, Val: val})
		}
