// ----- YAML writing -----

type yamlWriter struct {
	parseKeys bool
	noNum     bool
}

var errNilYAMLKey = errors.New("reflect: call of reflect.Value.Set on zero Value")

func writeYAML(v interface{}, opts options) ([]byte, error) {
	w := &yamlWriter{parseKeys: opts.parseKeys, noNum: opts.noNum}
