{"command":"cat > tomlconv.go <<'EOF'
package main

import (
	"app/order"
	"bytes"
	"math"
	"reflect"
	"sort"
	"strconv"
	"strings"

	"github.com/BurntSushi/toml"
)

// ---- parsing, preserving order via MetaData keys ----

type tNodeKind int

const (
	tScalar tNodeKind = iota
	tMap
	tSlice
)

type tNode struct {
	kind         tNodeKind
	scalar       interface{}
	children     map[string]*tNode
	order        []string
	elems        []*tNode
	isTableArray bool
	cur          int
	started      bool
	visited      bool
}

func buildSkeleton(raw interface{}) *tNode {
	switch x := raw.(type) {
	case map[string]interface{}:
		n := &tNode{kind: tMap, children: map[string]*tNode{}}
		for k, v := range x {
			n.children[k] = buildSkeleton(v)
		}
		return n
	case []map[string]interface{}:
		n := &tNode{kind: tSlice, isTableArray: true}
		for _, e := range x {
			n.elems = append(n.elems, buildSkeleton(e))
		}
		return n
	case []interface{}:
		n := &tNode{kind: tSlice}
		for _, e := range x {
			n.elems = append(n.elems, buildSkeleton(e))
		}
		return n
	default:
		return &tNode{kind: tScalar, scalar: raw}
	}
}

func (n *tNode) canAccept(segs []string) bool {
	if len(segs) == 0 {
		if n.kind == tSlice && n.isTableArray {
			if !n.started {
				return len(n.elems) > 0
			}
			return n.cur+1 < len(n.elems)
		}
		return !n.visited
	}
	switch n.kind {
	case tMap:
		c, ok := n.children[segs[0]]
		if !ok {
			return false
		}
		return c.canAccept(segs[1:])
	case tSlice:
		start := 0
		if n.started {
			start = n.cur
		}
		for i := start; i < len(n.elems); i++ {
			if n.elems[i].canAccept(segs) {
				return true
			}
		}
		return false
	default:
		return false
	}
}

func (n *tNode) selectElem(segs []string) int {
	start := 0
	if n.started {
		start = n.cur
	}
	for i := start; i < len(n.elems); i++ {
		if n.elems[i].canAccept(segs) {
			n.cur = i
			n.started = true
			return i
		}
	}
	if n.started {
		return n.cur
	}
	if len(n.elems) > 0 {
		n.started = true
		n.cur = 0
		return 0
	}
	return -1
}

func (n *tNode) descend(segs []string) *tNode {
	// n is the child node for a key segment; segs are remaining segments.
	if len(segs) == 0 {
		return n
	}
	switch n.kind {
	case tMap:
		return n
	case tSlice:
		idx := n.selectElem(segs)
		if idx < 0 {
			return nil
		}
		return n.elems[idx].descend(segs)
	default:
		return nil
	}
}

func (n *tNode) markTerminal() {
	if n.kind == tSlice && n.isTableArray {
		if !n.started {
			n.started = true
			n.cur = 0
			n.visited = true
		} else if n.cur+1 < len(n.elems) {
			n.cur++
		}
		return
	}
	n.visited = true
}

func (n *tNode) toValue() interface{} {
	switch n.kind {
	case tMap:
		keys := make([]string, 0, len(n.children))
		seen := map[string]bool{}
		for _, k := range n.order {
			if _, ok := n.children[k]; ok && !seen[k] {
				keys = append(keys, k)
				seen[k] = true
			}
		}
		var rest []string
		for k := range n.children {
			if !seen[k] {
				rest = append(rest, k)
			}
		}
		sort.Strings(rest)
		keys = append(keys, rest...)
		out := make(order.MapSlice, 0, len(keys))
		for _, k := range keys {
			out = append(out, order.MapItem{Key: k, Val: n.children[k].toValue()})
		}
		return out
	case tSlice:
		out := make([]interface{}, 0, len(n.elems))
		for _, e := range n.elems {
			out = append(out, e.toValue())
		}
		return out
	default:
		return n.scalar
	}
}

func parseTOML(data []byte) (interface{}, error) {
	var raw interface{}
	md, err := toml.Decode(string(data), &raw)
	if err != nil {
		return nil, err
	}
	if raw == nil {
		return order.MapSlice{}, nil
	}
	root := buildSkeleton(raw)
	for _, key := range md.Keys() {
		segs := []string(key)
		node := root
		for i, seg := range segs {
			if node == nil || node.kind != tMap {
				break
			}
			found := false
			for _, k := range node.order {
				if k == seg {
					found = true
					break
				}
			}
			if !found {
				if _, ok := node.children[seg]; ok {
					node.order = append(node.order, seg)
				}
			}
			child := node.children[seg]
			if child == nil {
				break
			}
			rem := segs[i+1:]
			if len(rem) == 0 {
				child.markTerminal()
				node = child
				break
			}
			node = child.descend(rem)
		}
	}
	return root.toValue(), nil
}

// ---- writing ----

type tomlFloat float64

func (f tomlFloat) MarshalTOML() ([]byte, error) {
	x := float64(f)
	switch {
	case math.IsInf(x, 1):
		return []byte("+inf"), nil
	case math.IsInf(x, -1):
		return []byte("-inf"), nil
	case math.IsNaN(x):
		return []byte("nan"), nil
	}
	s := strconv.FormatFloat(x, 'f', -1, 64)
	if !strings.Contains(s, ".") {
		s += ".0"
	}
	return []byte(s), nil
}

func tomlFieldName(i int) string {
	if i == 0 {
		return "A"
	}
	var rev []byte
	for i > 0 {
		rev = append(rev, byte('A'+i%26))
		i /= 26
	}
	for l, r := 0, len(rev)-1; l < r; l, r = l+1, r-1 {
		rev[l], rev[r] = rev[r], rev[l]
	}
	return string(rev)
}

var ifaceType = reflect.TypeOf((*interface{})(nil)).Elem()

func tomlConvert(v interface{}) interface{} {
	switch x := v.(type) {
	case order.MapSlice:
		fields := make([]reflect.StructField, len(x))
		vals := make([]interface{}, len(x))
		for i, item := range x {
			cv := tomlConvert(item.Val)
			vals[i] = cv
			var ft reflect.Type
			if cv == nil {
				ft = ifaceType
			} else {
				ft = reflect.TypeOf(cv)
			}
			fields[i] = reflect.StructField{
				Name: tomlFieldName(i),
				Type: ft,
				Tag:  reflect.StructTag("toml:" + strconv.Quote(item.Key)),
			}
		}
		st := reflect.StructOf(fields)
		sv := reflect.New(st).Elem()
		for i, cv := range vals {
			if cv != nil {
				sv.Field(i).Set(reflect.ValueOf(cv))
			}
		}
		return sv.Interface()
	case []interface{}:
		out := make([]interface{}, len(x))
		for i, e := range x {
			out[i] = tomlConvert(e)
		}
		return out
	case float64:
		return tomlFloat(x)
	case float32:
		return tomlFloat(float64(x))
	default:
		return v
	}
}

func writeTOML(v interface{}, opts options) ([]byte, error) {
	var buf bytes.Buffer
	enc := toml.NewEncoder(&buf)
	if opts.indent {
		enc.Indent = "  "
	} else {
		enc.Indent = ""
	}
	cv := tomlConvert(v)
	if err := enc.Encode(cv); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}
EOF
"}

