		return false
	}
}

func (n *tNode) selectElem(segs []string) int {
	start := 0
	if n.started {
		start = n.cur
	}
	for i := start; i < len(n.elems); i++ {
		if n.elems[i].canAccept(segs) {
			n.cur = i
			n.started = true
			return i
		}
	}
	if n.started {
		return n.cur
	}
	if len(n.elems) > 0 {
		n.started = true
		n.cur = 0
		return 0
	}
	return -1
