package main

import (
	"app/order"
	"bytes"
	"errors"
	"fmt"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// ---------- positions & tokens ----------

type hPos struct {
	Line, Col int
}

func (p hPos) String() string { return fmt.Sprintf("%d:%d", p.Line, p.Col) }

type hTokType int

const (
	hEOF hTokType = iota
	hIdent
	hString
	hHeredoc
	hNumber
	hFloat
	hBool
	hNull
	hLBrace
	hRBrace
	hLBrack
	hRBrack
	hAssign
	hAdd
	hSub
	hComma
	hPeriod
	hColon
)

func (t hTokType) String() string {
	switch t {
	case hEOF:
		return "EOF"
	case hIdent:
		return "IDENT"
	case hString:
		return "STRING"
	case hHeredoc:
		return "HEREDOC"
	case hNumber:
		return "NUMBER"
	case hFloat:
		return "FLOAT"
	case hBool:
		return "BOOL"
	case hNull:
		return "NULL"
	case hLBrace:
		return "LBRACE"
	case hRBrace:
		return "RBRACE"
	case hLBrack:
		return "LBRACK"
	case hRBrack:
		return "RBRACK"
	case hAssign:
		return "ASSIGN"
	case hAdd:
		return "ADD"
	case hSub:
		return "SUB"
	case hComma:
		return "COMMA"
	case hPeriod:
		return "PERIOD"
	case hColon:
		return "COLON"
	}
	return "ILLEGAL"
}

type hToken struct {
	Type hTokType
	Text string // raw token text
	Str  string // decoded string value (for STRING/HEREDOC)
	Pos  hPos
}

type hScanError struct {
	Pos hPos
	Msg string
}

func (e *hScanError) Error() string { return e.Msg }

// ---------- scanner core ----------

type scanCore struct {
	src []rune
	off int // index of current ch, len(src) at EOF
}

func newScanCore(data []byte) *scanCore {
	return &scanCore{src: []rune(string(data))}
}

func (s *scanCore) ch() rune {
	if s.off >= len(s.src) {
		return -1
	}
	return s.src[s.off]
}

func (s *scanCore) peek() rune {
	if s.off+1 >= len(s.src) {
		return -1
	}
	return s.src[s.off+1]
}

func (s *scanCore) next() {
	if s.off < len(s.src) {
		s.off++
	}
}

func (s *scanCore) posAt(off int) hPos {
	line, col := 1, 1
	for i := 0; i < off && i < len(s.src); i++ {
		if s.src[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	if off > len(s.src) {
		col += off - len(s.src)
	}
	return hPos{line, col}
}

func (s *scanCore) pos() hPos { return s.posAt(s.off) }

func isLetter(ch rune) bool { return ch == '_' || unicode.IsLetter(ch) }
func isDigit(ch rune) bool  { return unicode.IsDigit(ch) }

func digitVal(ch rune) int {
	switch {
	case '0' <= ch && ch <= '9':
		return int(ch - '0')
	case 'a' <= ch && ch <= 'f':
		return int(ch-'a') + 10
	case 'A' <= ch && ch <= 'F':
		return int(ch-'A') + 10
	}
	return 16
}

// scanEscape processes an escape sequence; s.ch() is the char after '\\'.
// It appends the decoded value to buf (if buf != nil) and advances past it.
func (s *scanCore) scanEscape(buf *bytes.Buffer) error {
	ch := s.ch()
	simple := func(r rune) error {
		if buf != nil {
			buf.WriteRune(r)
		}
		s.next()
		return nil
	}
	switch ch {
	case 'a':
		return simple('\a')
	case 'b':
		return simple('\b')
	case 'f':
		return simple('\f')
	case 'n':
		return simple('\n')
	case 'r':
		return simple('\r')
	case 't':
		return simple('\t')
	case 'v':
		return simple('\v')
	case '\\':
		return simple('\\')
	case '"':
		return simple('"')
	case 'x', 'u', 'U':
		n := 2
		if ch == 'u' {
			n = 4
		} else if ch == 'U' {
			n = 8
		}
		s.next()
		val := 0
		for i := 0; i < n; i++ {
			d := digitVal(s.ch())
			if d >= 16 {
				return &hScanError{s.pos(), "illegal char escape"}
			}
			val = val*16 + d
			s.next()
		}
		if buf != nil {
			if ch == 'x' {
				buf.WriteByte(byte(val))
			} else {
				r := rune(val)
				if val > utf8.MaxRune || (val >= 0xD800 && val <= 0xDFFF) {
					r = utf8.RuneError
				}
				buf.WriteRune(r)
			}
		}
		return nil
	default:
		if '0' <= ch && ch <= '7' {
			val := 0
			for i := 0; i < 3 && '0' <= s.ch() && s.ch() <= '7'; i++ {
				val = val*8 + int(s.ch()-'0')
				s.next()
			}
			if buf != nil {
				buf.WriteByte(byte(val))
			}
			return nil
		}
		return &hScanError{s.pos(), "illegal char escape"}
	}
}

// ---------- native HCL scanner ----------

type hScanner struct {
	*scanCore
}

func (s *hScanner) scanComment() error {
	// s.ch() == '#', or '/' with next '/' or '*'
	if s.ch() == '#' || s.peek() == '/' {
		for s.ch() != '\n' && s.ch() != -1 {
			s.next()
		}
		return nil
	}
	// block comment /*
	s.next() // '/'
	s.next() // '*'
	for {
		if s.ch() == -1 {
			return &hScanError{s.posAt(len(s.src)), "comment not terminated"}
		}
		if s.ch() == '*' && s.peek() == '/' {
			s.next()
			s.next()
			return nil
		}
		s.next()
	}
}

func (s *hScanner) skipSpaceAndComments() error {
	for {
		ch := s.ch()
		if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
			s.next()
			continue
		}
		if ch == '#' {
			if err := s.scanComment(); err != nil {
				return err
			}
			continue
		}
		if ch == '/' {
			if s.peek() == '/' || s.peek() == '*' {
				if err := s.scanComment(); err != nil {
					return err
				}
				continue
			}
			return &hScanError{s.pos(), "expected '/' for comment"}
		}
		return nil
	}
}

func (s *hScanner) scanIdent(start hPos) hToken {
	from := s.off
	for {
		ch := s.ch()
		if isLetter(ch) || isDigit(ch) || ch == '-' || ch == '.' {
			s.next()
		} else {
			break
		}
	}
	text := string(s.src[from:s.off])
	typ := hIdent
	if text == "true" || text == "false" {
		typ = hBool
	}
	return hToken{Type: typ, Text: text, Pos: start}
}

func (s *hScanner) scanNumber(start hPos) (hToken, error) {
	from := s.off
	typ := hNumber
	if s.ch() == '0' && (s.peek() == 'x' || s.peek() == 'X') {
		s.next() // 0
		s.next() // x
		if digitVal(s.ch()) >= 16 {
			return hToken{}, &hScanError{s.pos(), "illegal hexadecimal number"}
		}
		for digitVal(s.ch()) < 16 {
			s.next()
		}
		return hToken{Type: hNumber, Text: string(s.src[from:s.off]), Pos: start}, nil
	}
	sawDot := false
	if s.ch() == '.' {
		typ = hFloat
		sawDot = true
		s.next()
	}
	for isDigit(s.ch()) {
		s.next()
	}
	if !sawDot && s.ch() == '.' {
		typ = hFloat
		s.next()
		for isDigit(s.ch()) {
			s.next()
		}
	}
	if s.ch() == 'e' || s.ch() == 'E' {
		typ = hFloat
		s.next()
		if s.ch() == '+' || s.ch() == '-' {
			s.next()
		}
		for isDigit(s.ch()) {
			s.next()
		}
	}
	return hToken{Type: typ, Text: string(s.src[from:s.off]), Pos: start}, nil
}

func (s *hScanner) scanString(start hPos) (hToken, error) {
	from := s.off
	s.next() // opening quote
	var buf bytes.Buffer
	for {
		ch := s.ch()
		if ch == '"' {
			s.next()
			break
		}
		if ch == -1 {
			return hToken{}, &hScanError{s.pos(), "literal not terminated"}
		}
		if ch == '\n' {
			// Consume through the closing quote (or EOF) like the reference,
			// reporting the error at the end position.
			for s.ch() != '"' && s.ch() != -1 {
				s.next()
			}
			if s.ch() == '"' {
				s.next()
			}
			return hToken{}, &hScanError{s.pos(), "literal not terminated"}
		}
		if ch == '\\' {
			s.next()
			if err := s.scanEscape(&buf); err != nil {
				return hToken{}, err
			}
			continue
		}
		buf.WriteRune(ch)
		s.next()
	}
	return hToken{Type: hString, Text: string(s.src[from:s.off]), Str: buf.String(), Pos: start}, nil
}

func (s *hScanner) scanHeredoc(start hPos) (hToken, error) {
	// s.ch() == '<'
	s.next()
	if s.ch() != '<' {
		return hToken{}, &hScanError{s.pos(), "heredoc expected second '<', didn't see it"}
	}
	s.next()
	indented := false
	if s.ch() == '-' {
		indented = true
		s.next()
	}
	markerStart := s.off
	for isLetter(s.ch()) || isDigit(s.ch()) || s.ch() == '_' {
		s.next()
	}
	marker := string(s.src[markerStart:s.off])
	if marker == "" || (s.ch() != '\n' && s.ch() != '\r' && s.ch() != -1) {
		return hToken{}, &hScanError{s.pos(), "invalid characters in heredoc anchor"}
	}
	// consume to end of anchor line
	if s.ch() == '\r' {
		s.next()
	}
	if s.ch() == '\n' {
		s.next()
	} else if s.ch() == -1 {
		return hToken{}, &hScanError{s.pos(), "heredoc not terminated"}
	}
	var content strings.Builder
	termIndent := ""
	for {
		if s.ch() == -1 {
			return hToken{}, &hScanError{s.pos(), "heredoc not terminated"}
		}
		// read one line (without the newline)
		lineStart := s.off
		for s.ch() != '\n' && s.ch() != -1 {
			s.next()
		}
		line := string(s.src[lineStart:s.off])
		line = strings.TrimSuffix(line, "\r")
		hasNL := s.ch() == '\n'
		if hasNL {
			// check terminator: optional spaces/tabs then marker, nothing else
			trimmed := strings.TrimLeft(line, " \t")
			ws := line[:len(line)-len(trimmed)]
			if trimmed == marker {
				if indented && ws == "" {
					// not a terminator in indented mode; treat as content
					content.WriteString(line)
					content.WriteString("\n")
					s.next()
					continue
				}
				termIndent = ws
				s.next() // newline
				if !indented {
					content.WriteString(ws)
					return hToken{Type: hHeredoc, Text: content.String(), Str: content.String(), Pos: start}, nil
				}
				text := content.String()
				if termIndent != "" {
					text = stripHeredocIndent(text, termIndent)
				}
				return hToken{Type: hHeredoc, Text: text, Str: text, Pos: start}, nil
			}
			content.WriteString(line)
			content.WriteString("\n")
			s.next()
			continue
		}
		// EOF without newline on this line
		return hToken{}, &hScanError{s.pos(), "heredoc not terminated"}
	}
}

func stripHeredocIndent(content, indent string) string {
	if content == "" {
		return content
	}
	lines := strings.SplitAfter(content, "\n")
	// All non-final lines (excluding the empty piece after trailing \n)
	// must start with the indent for stripping to happen at all.
	parts := lines
	if len(parts) > 0 && parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	for _, ln := range parts {
		if !strings.HasPrefix(ln, indent) {
			return content
		}
	}
	var b strings.Builder
	for _, ln := range lines {
		b.WriteString(strings.TrimPrefix(ln, indent))
	}
	return b.String()
}

func (s *hScanner) scan() (hToken, error) {
	if err := s.skipSpaceAndComments(); err != nil {
		return hToken{}, err
	}
	start := s.pos()
	ch := s.ch()
	switch {
	case ch == -1:
		return hToken{Type: hEOF, Pos: start}, nil
	case isLetter(ch):
		return s.scanIdent(start), nil
	case isDigit(ch) || (ch == '.' && isDigit(s.peek())):
		return s.scanNumber(start)
	case ch == '"':
		return s.scanString(start)
	case ch == '<':
		return s.scanHeredoc(start)
	case ch == '{':
		s.next()
		return hToken{Type: hLBrace, Text: "{", Pos: start}, nil
	case ch == '}':
		s.next()
		return hToken{Type: hRBrace, Text: "}", Pos: start}, nil
	case ch == '[':
		s.next()
		return hToken{Type: hLBrack, Text: "[", Pos: start}, nil
	case ch == ']':
		s.next()
		return hToken{Type: hRBrack, Text: "]", Pos: start}, nil
	case ch == '=':
		s.next()
		return hToken{Type: hAssign, Text: "=", Pos: start}, nil
	case ch == '+':
		s.next()
		return hToken{Type: hAdd, Text: "+", Pos: start}, nil
	case ch == '-':
		s.next()
		return hToken{Type: hSub, Text: "-", Pos: start}, nil
	case ch == ',':
		s.next()
		return hToken{Type: hComma, Text: ",", Pos: start}, nil
	case ch == '.':
		s.next()
		return hToken{Type: hPeriod, Text: ".", Pos: start}, nil
	default:
		return hToken{}, &hScanError{start, "illegal char"}
	}
}

// ---------- AST ----------

type hLiteral struct {
	Tok hToken
}

type hList struct {
	Elems []interface{} // of hNode
}

type hObject struct {
	List *hObjectList
}

type hObjectList struct {
	Items []*hItem
}

type hItem struct {
	Keys    []string
	KeyRaws []string
	Val     interface{} // *hLiteral, *hList, *hObject, or nil
}

// ---------- native parser ----------

type hParser struct {
	sc      *hScanner
	tok     hToken
	scanned bool
}

func (p *hParser) scan() (hToken, error) {
	if p.scanned {
		p.scanned = false
		return p.tok, nil
	}
	t, err := p.sc.scan()
	if err != nil {
		return t, wrapNativeErr(err)
	}
	return t, nil
}

func (p *hParser) unscan(t hToken) {
	p.tok = t
	p.scanned = true
}

func wrapNativeErr(err error) error {
	if se, ok := err.(*hScanError); ok {
		return fmt.Errorf("At %s: %s", se.Pos.String(), se.Msg)
	}
	return err
}

func atErr(pos hPos, format string, args ...interface{}) error {
	return fmt.Errorf("At %s: %s", pos.String(), fmt.Sprintf(format, args...))
}

// parseObjectList parses items until EOF (top) or RBRACE (inObject).
// Returns the list and the terminating token.
func (p *hParser) parseObjectList(inObject bool) (*hObjectList, hToken, error) {
	list := &hObjectList{}
	for {
		tok, err := p.scan()
		if err != nil {
			return nil, tok, err
		}
		if tok.Type == hEOF {
			return list, tok, nil
		}
		if tok.Type == hRBrace && inObject {
			return list, tok, nil
		}
		p.unscan(tok)
		item, err := p.parseObjectItem()
		if err != nil {
			return nil, tok, err
		}
		if item != nil {
			list.Items = append(list.Items, item)
		}
		// optional comma
		tok, err = p.scan()
		if err != nil {
			return nil, tok, err
		}
		if tok.Type == hComma {
			continue
		}
		p.unscan(tok)
	}
}

func (p *hParser) parseObjectItem() (*hItem, error) {
	var keys []string
	var raws []string
	var delim hToken
	for {
		tok, err := p.scan()
		if err != nil {
			return nil, err
		}
		switch tok.Type {
		case hIdent:
			keys = append(keys, tok.Text)
			raws = append(raws, tok.Text)
		case hString:
			keys = append(keys, tok.Str)
			raws = append(raws, tok.Text)
		case hAssign, hLBrace, hEOF, hRBrace:
			delim = tok
			goto haveKeys
		default:
			return nil, atErr(tok.Pos, "expected: IDENT | STRING | ASSIGN | LBRACE got: %s", tok.Type)
		}
	}
haveKeys:
	if len(keys) == 0 {
		if delim.Type == hAssign {
			return nil, atErr(delim.Pos, "no object keys found!")
		}
		if delim.Type == hLBrace {
			return nil, atErr(delim.Pos, "expected: IDENT | STRING got: LBRACE")
		}
		return nil, atErr(delim.Pos, "expected: IDENT | STRING | ASSIGN | LBRACE got: %s", delim.Type)
	}
	switch delim.Type {
	case hAssign:
		if len(keys) > 1 {
			return nil, atErr(delim.Pos, "nested object expected: LBRACE got: ASSIGN")
		}
		// EOF directly after '=' yields a dropped item.
		tok, err := p.scan()
		if err != nil {
			return nil, err
		}
		if tok.Type == hEOF {
			return nil, nil
		}
		p.unscan(tok)
		val, err := p.parseValue(false)
		if err != nil {
			return nil, err
		}
		return &hItem{Keys: keys, KeyRaws: raws, Val: val}, nil
	case hLBrace:
		obj, err := p.parseObjectAfterBrace(delim)
		if err != nil {
			return nil, err
		}
		return &hItem{Keys: keys, KeyRaws: raws, Val: obj}, nil
	default:
		return nil, atErr(delim.Pos, "key '%s' expected start of object ('{') or assignment ('=')", strings.Join(raws, " "))
	}
}

func (p *hParser) parseObjectAfterBrace(brace hToken) (*hObject, error) {
	_ = brace
	list, term, err := p.parseObjectList(true)
	if err != nil {
		return nil, err
	}
	if term.Type == hEOF {
		return nil, atErr(term.Pos, "object expected closing RBRACE got: EOF")
	}
	return &hObject{List: list}, nil
}

func (p *hParser) parseValue(inList bool) (interface{}, error) {
	tok, err := p.scan()
	if err != nil {
		return nil, err
	}
	switch tok.Type {
	case hString, hHeredoc, hNumber, hFloat, hBool:
		return &hLiteral{Tok: tok}, nil
	case hSub:
		tok2, err := p.scan()
		if err != nil {
			return nil, err
		}
		if tok2.Type == hNumber || tok2.Type == hFloat {
			t := tok2
			t.Text = "-" + tok2.Text
			t.Pos = tok.Pos
			return &hLiteral{Tok: t}, nil
		}
		if inList {
			return nil, atErr(tok.Pos, "unexpected token while parsing list: %s", tok.Type)
		}
		return nil, atErr(tok.Pos, "Unknown token: %s %s %s", tok.Pos, tok.Type, tok.Text)
	case hLBrack:
		return p.parseList()
	case hLBrace:
		return p.parseObjectAfterBrace(tok)
	default:
		if inList {
			return nil, atErr(tok.Pos, "unexpected token while parsing list: %s", tok.Type)
		}
		return nil, atErr(tok.Pos, "Unknown token: %s %s %s", tok.Pos, tok.Type, tok.Text)
	}
}

func (p *hParser) parseList() (*hList, error) {
	list := &hList{}
	for {
		tok, err := p.scan()
		if err != nil {
			return nil, err
		}
		switch tok.Type {
		case hRBrack:
			return list, nil
		case hComma:
			continue
		case hEOF:
			return nil, atErr(tok.Pos, "unexpected token while parsing list: EOF")
		}
		p.unscan(tok)
		elem, err := p.parseValue(true)
		if err != nil {
			return nil, err
		}
		list.Elems = append(list.Elems, elem)
		tok, err = p.scan()
		if err != nil {
			return nil, err
		}
		if tok.Type == hComma || tok.Type == hRBrack {
			p.unscan(tok)
			continue
		}
		return nil, atErr(tok.Pos, "error parsing list, expected comma or list end, got: %s", tok.Type)
	}
}

// ---------- AST -> data conversion ----------

func literalValue(tok hToken) (interface{}, error) {
	switch tok.Type {
	case hString, hHeredoc:
		return tok.Str, nil
	case hNumber:
		return strconv.ParseInt(tok.Text, 0, 64)
	case hFloat:
		return strconv.ParseFloat(tok.Text, 64)
	case hBool:
		return strconv.ParseBool(tok.Text)
	case hNull:
		return "", nil
	default:
		return tok.Text, nil
	}
}

func nodeValue(node interface{}) (interface{}, error) {
	switch n := node.(type) {
	case nil:
		return nil, nil
	case *hLiteral:
		return literalValue(n.Tok)
	case *hList:
		out := make([]interface{}, 0, len(n.Elems))
		for _, e := range n.Elems {
			v, err := nodeValue(e)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
		return out, nil
	case *hObject:
		return convertObjectList(n.List)
	default:
		return nil, fmt.Errorf("unknown node %T", node)
	}
}

func convertObjectList(list *hObjectList) (order.MapSlice, error) {
	if list == nil {
		return order.MapSlice{}, nil
	}
	// check empty keys first
	for _, item := range list.Items {
		if len(item.Keys) == 0 {
			return nil, errors.New("empty key at line 0")
		}
	}
	// group by first key, preserving order
	type group struct {
		key   string
		items []*hItem
	}
	var groups []*group
	byKey := map[string]*group{}
	for _, item := range list.Items {
		k := item.Keys[0]
		g := byKey[k]
		if g == nil {
			g = &group{key: k}
			byKey[k] = g
			groups = append(groups, g)
		}
		g.items = append(g.items, item)
	}
	result := order.MapSlice{}
	for _, g := range groups {
		hasLabel := false
		for _, it := range g.items {
			if len(it.Keys) > 1 {
				hasLabel = true
				break
			}
		}
		if hasLabel {
			stripped := &hObjectList{}
			for _, it := range g.items {
				ni := *it
				if len(it.Keys) > 0 {
					ni.Keys = it.Keys[1:]
				}
				stripped.Items = append(stripped.Items, &ni)
			}
			child, err := convertObjectList(stripped)
			if err != nil {
				return nil, err
			}
			result = append(result, order.MapItem{Key: g.key, Val: []interface{}{child}})
			continue
		}
		var cur interface{}
		has := false
		appendElem := func(elem interface{}) error {
			if !has {
				cur = []interface{}{}
				has = true
			}
			slice, ok := cur.([]interface{})
			if !ok {
				return fmt.Errorf("cannot append '%#v' to '%#v", elem, cur)
			}
			cur = append(slice, elem)
			return nil
		}
		for _, it := range g.items {
			switch n := it.Val.(type) {
			case nil:
				continue
			case *hLiteral:
				v, err := literalValue(n.Tok)
				if err != nil {
					return nil, err
				}
				if has {
					if _, isSlice := cur.([]interface{}); isSlice {
						return nil, fmt.Errorf("cannot set '%#v' over '%#v", v, cur)
					}
				}
				cur = v
				has = true
			case *hList:
				for _, e := range n.Elems {
					v, err := nodeValue(e)
					if err != nil {
						return nil, err
					}
					if err := appendElem(v); err != nil {
						return nil, err
					}
				}
			case *hObject:
				body, err := convertObjectList(n.List)
				if err != nil {
					return nil, err
				}
				if err := appendElem(body); err != nil {
					return nil, err
				}
			default:
				return nil, fmt.Errorf("unknown node %T", it.Val)
			}
		}
		if has {
			result = append(result, order.MapItem{Key: g.key, Val: cur})
		}
	}
	return result, nil
}

func parseHCLNative(data []byte) (interface{}, error) {
	sc := &hScanner{newScanCore(data)}
	p := &hParser{sc: sc}
	list, _, err := p.parseObjectList(false)
	if err != nil {
		return nil, err
	}
	return convertObjectList(list)
}

func parseHCL(data []byte) (interface{}, error) {
	trimmed := bytes.TrimLeft(data, " \t\r\n")
	if len(trimmed) > 0 && trimmed[0] == '{' {
		list, err := parseHCLJSONToList(data)
		if err != nil {
			return nil, err
		}
		return convertObjectList(list)
	}
	return parseHCLNative(data)
}
