// ---------- JSON-mode parser ----------

type jParser struct {
	sc      *jScanner
	tok     hToken
	scanned bool
}

func (p *jParser) scan() (hToken, error) {
	if p.scanned {
		p.scanned = false
		return p.tok, nil
	}
	t, err := p.sc.scan()
	if err != nil {
		return t, wrapJSONErr(err)
	}
	return t, nil
}

func (p *jParser) unscan(t hToken) { p.tok = t; p.scanned = true }

func (p *jParser) parseTop() (*hObjectList, error) {
	tok, err := p.scan()
	if err != nil {
		return nil, err
	}
	if tok.Type != hLBrace {
		return nil, fmt.Errorf("Expected object, got unknown token: %s %s %s", tok.Pos, tok.Type, tok.Text)
	}
	list, err := p.parseObjectBody()
	if err != nil {
		return nil, err
	}
	flattenObjectList(list)
	return list, nil
}

// parseObjectBody parses after '{' up to '}' or EOF.
func (p *jParser) parseObjectBody() (*hObjectList, error) {
	list := &hObjectList{}
	for {
		tok, err := p.scan()
		if err != nil {
			return nil, err
		}
		if tok.Type == hRBrace || tok.Type == hEOF {
			return list, nil
		}
		if tok.Type == hComma {
			continue
		}
		if tok.Type != hString {
			return nil, fmt.Errorf("expected: STRING got: %s", tok.Type)
		}
		keyTok := tok
		// key string value
		keyStr, err := strconv.Unquote(keyTok.Text)
		if err != nil {
			return nil, fmt.Errorf("unexpected failure: unquote %s err: %s", keyTok.Text, err.Error())
		}
		tok2, err := p.scan()
		if err != nil {
			return nil, err
		}
		if tok2.Type != hColon {
			if tok2.Type == hRBrace || tok2.Type == hEOF {
				return list, nil
			}
			if tok2.Type == hComma {
				continue
			}
			// Missing colon; treat token as start of value if possible.
			p.unscan(tok2)
		}
		val, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		if val == nil {
			continue
		}
