		if lit, ok := val.(*hLiteral); ok && lit.Tok.Type == hString {
			str, err := strconv.Unquote(lit.Tok.Text)
			if err != nil {
				return nil, fmt.Errorf("unexpected failure: unquote %s err: %s", lit.Tok.Text, err.Error())
			}
			lit.Tok.Str = str
		}
		list.Items = append(list.Items, &hItem{Keys: []string{keyStr}, KeyRaws: []string{keyTok.Text}, Val: val})
