func (p *jParser) parseList() (*hList, error) {
	list := &hList{}
	first := true
	wrapped := false
	for {
		tok, err := p.scan()
		if err != nil {
			return nil, err
		}
		switch tok.Type {
		case hEOF:
			return list, nil
		case hRBrack:
			return list, nil
		case hRBrace:
			p.unscan(tok)
			return list, nil
