			lit := &hLiteral{Tok: tok}
			if tok.Type == hString {
				str, err := strconv.Unquote(tok.Text)
				if err != nil {
					return nil, fmt.Errorf("unexpected failure: unquote %s err: %s", tok.Text, err.Error())
				}
				lit.Tok.Str = str
			}
			list.Elems = append(list.Elems, lit)
			first = false
		default:
			return nil, fmt.Errorf("unexpected token while parsing list: %s", tok.Type)
		}
	}
}

func parseHCLJSONToList(data []byte) (*hObjectList, error) {
	p := &jParser{sc: &jScanner{newScanCore(data)}}
	return p.parseTop()
}

// ---------- flatten ----------

func flattenObjectList(list *hObjectList) {
	if list == nil {
		return
	}
	var out []*hItem
	for _, item := range list.Items {
		out = append(out, flattenItem(item)...)
	}
	list.Items = out
}

func flattenItem(item *hItem) []*hItem {
	switch v := item.Val.(type) {
	case *hObject:
		// decide merge eligibility based on the pre-flatten sole child
		mergeEligible := false
		if v.List != nil && len(v.List.Items) == 1 {
			if _, ok := v.List.Items[0].Val.(*hObject); ok {
				mergeEligible = true
			}
		}
		flattenObjectList(v.List)
		if mergeEligible && v.List != nil && len(v.List.Items) == 1 {
			sole := v.List.Items[0]
			if _, ok := sole.Val.(*hObject); ok {
				merged := &hItem{
					Keys:    append(append([]string{}, item.Keys...), sole.Keys...),
					KeyRaws: append(append([]string{}, item.KeyRaws...), sole.KeyRaws...),
					Val:     sole.Val,
				}
				return []*hItem{merged}
			}
		}
		return []*hItem{item}
	case *hList:
		// flatten inside object elements
		for _, e := range v.Elems {
			if obj, ok := e.(*hObject); ok {
				flattenObjectList(obj.List)
			}
		}
		if len(v.Elems) > 0 {
			allObj := true
			for _, e := range v.Elems {
				if _, ok := e.(*hObject); !ok {
					allObj = false
					break
				}
			}
			if allObj {
				var out []*hItem
				for _, e := range v.Elems {
					ni := &hItem{Keys: item.Keys, KeyRaws: item.KeyRaws, Val: e}
					out = append(out, flattenItemObjectOnly(ni)...)
				}
				return out
			}
		}
		return []*hItem{item}
	default:
		return []*hItem{item}
	}
}

func flattenItemObjectOnly(item *hItem) []*hItem {
	// item.Val is an *hObject that has already had its list flattened;
	// apply the merge rule based on its sole child now.
	if v, ok := item.Val.(*hObject); ok {
		if v.List != nil && len(v.List.Items) == 1 {
			sole := v.List.Items[0]
			// sole's list was already flattened; merge only if sole still
			// holds an object which came from an object (its Items were not
			// produced by a list expansion). We approximate by checking that
			// sole was not itself the product of a list: list expansion is
			// already done, so a sole item with an object value whose own
			// expansion would have been recorded is ambiguous. Use the
			// pre-expansion marker stored in KeyRaws length? Instead, rely on
			// flattenItem's object branch for the general case and only merge
			// here when sole has >1 keys (a label chain) or its value object
			// is non-trivially nested.
			if _, ok := sole.Val.(*hObject); ok && soleFromObject(sole) {
				merged := &hItem{
					Keys:    append(append([]string{}, item.Keys...), sole.Keys...),
					KeyRaws: append(append([]string{}, item.KeyRaws...), sole.KeyRaws...),
					Val:     sole.Val,
				}
				return []*hItem{merged}
			}
		}
	}
	return []*hItem{item}
}

// soleFromObject reports whether a flattened sole item originated from a
// JSON object value rather than a list-of-objects expansion. We track this
// by re-examining: after flattenObjectList, an item that came from a list
// expansion inside this object would have been produced by flattenItem's
// list branch. Without explicit tracking we approximate: an item whose
// value is an object and that has exactly one key is assumed to be from an
// object, since the reference merges chains like a->b->c regardless.
// The distinguishing case (a -> {b: [{...}]}) is handled at the parent
// level in flattenItem (mergeEligible computed pre-flatten), so returning
// true here is correct for list-expanded parents like a: [{b: {c: 1}}].
func soleFromObject(item *hItem) bool { return true }

// ---------- printer ----------

func writeHCL(v interface{}, opts options) ([]byte, error) {
	jb := marshalJSONValue(v, false, false)
	list, err := parseHCLJSONToList(jb)
	if err != nil {
		return nil, err
	}
	out := printObjectList(list, 0)
	return []byte(out), nil
}

func hclIndent(level int) string { return strings.Repeat("  ", level) }

func printObjectList(list *hObjectList, level int) string {
	if list == nil || len(list.Items) == 0 {
		return ""
	}
	parts := make([]string, 0, len(list.Items))
	for _, item := range list.Items {
		parts = append(parts, printItem(item, level))
	}
	return strings.Join(parts, "\n\n")
}

func printItem(item *hItem, level int) string {
	ind := hclIndent(level)
	keys := strings.Join(item.KeyRaws, " ")
	switch v := item.Val.(type) {
	case *hObject:
		if len(item.KeyRaws) > 1 {
			return ind + keys + " " + printObject(v, level)
		}
		return ind + keys + " = " + printObject(v, level)
	case *hList:
		return ind + keys + " = " + printList(v, level)
	case *hLiteral:
		return ind + keys + " = " + printLiteral(v)
	case nil:
		return ind + keys + " = "
	default:
		return ind + keys + " = "
	}
}

func printObject(obj *hObject, level int) string {
	if obj.List == nil || len(obj.List.Items) == 0 {
		return "{}"
	}
	var b bytes.Buffer
	b.WriteString("{\n")
	b.WriteString(printObjectList(obj.List, level+1))
	b.WriteString("\n")
	b.WriteString(hclIndent(level))
	b.WriteString("}")
	return b.String()
}

func printList(list *hList, level int) string {
	if len(list.Elems) == 0 {
		return "[]"
	}
	hasObj := false
	for _, e := range list.Elems {
		if _, ok := e.(*hObject); ok {
			hasObj = true
		}
		if _, ok := e.(*hList); ok {
			hasObj = true
		}
	}
	if !hasObj {
		parts := make([]string, 0, len(list.Elems))
		for _, e := range list.Elems {
			parts = append(parts, printValue(e, level))
		}
		return "[" + strings.Join(parts, ", ") + "]"
	}
	var b bytes.Buffer
	b.WriteString("[\n")
	for _, e := range list.Elems {
		b.WriteString(hclIndent(level + 1))
		b.WriteString(printValue(e, level+1))
		b.WriteString(",\n")
	}
	b.WriteString(hclIndent(level))
	b.WriteString("]")
	return b.String()
}

func printValue(v interface{}, level int) string {
	switch x := v.(type) {
	case *hObject:
		return printObject(x, level)
	case *hList:
		return printList(x, level)
	case *hLiteral:
		return printLiteral(x)
	default:
		return ""
	}
}

func printLiteral(lit *hLiteral) string {
	if lit.Tok.Type == hNull {
		return ""
	}
	return lit.Tok.Text
}
EOF
"}

