		switch text {
		case "true", "false":
			return hToken{Type: hBool, Text: text, Pos: start}, nil
		case "null":
			return hToken{Type: hNull, Text: text, Pos: start}, nil
		default:
			pos := s.posAt(s.off - 1)
			return hToken{}, &hScanError{pos, "illegal char"}
		}
	default:
		if ch == '+' || ch == '=' {
			return hToken{}, &hScanError{start, "illegal char: " + string(ch)}
		}
		return hToken{}, &hScanError{start, "illegal char"}
	}
}

// ---------- JSON-mode parser ----------

type jParser struct {
	sc      *jScanner
	tok     hToken
	scanned bool
}

func (p *jParser) scan() (hToken, error) {
	if p.scanned {
		p.scanned = false
		return p.tok, nil
	}
	t, err := p.sc.scan()
	if err != nil {
