}

func (p *jParser) unscan(t hToken) { p.tok = t; p.scanned = true }

func (p *jParser) parseTop() (*hObjectList, error) {
	tok, err := p.scan()
	if err != nil {
		return nil, err
	}
	if tok.Type != hLBrace {
		return nil, fmt.Errorf("Expected object, got unknown token: %s %s %s", tok.Pos, tok.Type, tok.Text)
	}
