// parseObjectBody parses after '{' up to '}' or EOF.
func (p *jParser) parseObjectBody() (*hObjectList, error) {
	list := &hObjectList{}
	for {
		tok, err := p.scan()
		if err != nil {
			return nil, err
		}
		if tok.Type == hRBrace || tok.Type == hEOF {
			return list, nil
		}
		if tok.Type == hComma {
			continue
		}
		if tok.Type != hString {
			return nil, fmt.Errorf("expected: STRING got: %s", tok.Type)
		}
		keyTok := tok
		// key string value
		keyStr, err := strconv.Unquote(keyTok.Text)
		if err != nil {
			return nil, fmt.Errorf("unexpected failure: unquote %s err: %s", keyTok.Text, err.Error())
		}
		tok2, err := p.scan()
		if err != nil {
			return nil, err
		}
