	case hString, hNumber, hFloat, hBool, hNull:
		lit := &hLiteral{Tok: tok}
		if tok.Type == hString {
			str, err := strconv.Unquote(tok.Text)
			if err != nil {
				return nil, fmt.Errorf("unexpected failure: unquote %s err: %s", tok.Text, err.Error())
			}
			lit.Tok.Str = str
		}
		return lit, nil
	case hLBrace:
		list, err := p.parseObjectBody()
		if err != nil {
			return nil, err
		}
		return &hObject{List: list}, nil
	case hLBrack:
		return p.parseList()
	case hRBrace, hEOF:
		p.unscan(tok)
		return nil, nil
	case hComma:
		return nil, nil
	default:
		p.unscan(tok)
		return nil, nil
	}
}

func (p *jParser) parseList() (*hList, error) {
	list := &hList{}
	first := true
	wrapped := false
	for {
		tok, err := p.scan()
		if err != nil {
			return nil, err
		}
		switch tok.Type {
		case hEOF:
			return list, nil
		case hRBrack:
			return list, nil
		case hRBrace:
			p.unscan(tok)
			return list, nil
