	seen := false
	for _, e := range x {
		if e == nil {
			continue
		}
		seen = true
		if _, ok := e.(order.MapSlice); !ok {
			return false
		}
	}
	return seen
}

func tomlConvert(v interface{}) interface{} {
	switch x := v.(type) {
	case order.MapSlice:
		return tomlStructFromMap(x)
	case []interface{}:
		if isTOMLArrayTableSlice(x) {
			out := make([]interface{}, 0, len(x))
			for _, e := range x {
				if e == nil {
					continue
				}
				out = append(out, tomlConvert(e))
			}
			return out
		}
