	sv := reflect.New(st).Elem()
	for i, cv := range vals {
		if cv != nil {
			sv.Field(i).Set(reflect.ValueOf(cv))
		}
	}
	return sv.Interface()
}

func tomlConvertTableFieldValue(v interface{}) interface{} {
	switch x := v.(type) {
	case order.MapSlice:
		return tomlStructFromMap(x)
	case []interface{}:
		if isTOMLArrayTableSlice(x) {
			out := make([]interface{}, 0, len(x))
			for _, e := range x {
				if e == nil {
					continue
				}
				out = append(out, tomlConvertTableFieldValue(e))
			}
			return out
		}
		return tomlConvertInlineValue(x)
	case float64:
		return tomlFloat(x)
	case float32:
		return tomlFloat(float64(x))
	default:
		return v
	}
}

func tomlConvertInlineValue(v interface{}) interface{} {
	switch x := v.(type) {
	case order.MapSlice:
		return newTOMLInlineMap(x)
	case []interface{}:
		out := make([]interface{}, 0, len(x))
		for _, e := range x {
			if e == nil {
				continue
			}
			out = append(out, tomlConvertInlineValue(e))
		}
		return out
	case float64:
		return tomlFloat(x)
	case float32:
		return tomlFloat(float64(x))
	default:
		return v
	}
}

// tomlInlineMap renders an inline table the way the older TOML
// encoder used by the reference does, including its separator
// placement quirks when scalar and table fields are reordered.
type tomlInlineMap struct {
	fields []tomlInlineField
}

type tomlInlineField struct {
	orig    int
	key     string
	val     interface{}
	cat     int // 0 scalar, 1 table
	written bool
}

func tomlInlineCategory(v interface{}) int {
	switch x := v.(type) {
	case order.MapSlice:
		return 1
	case []interface{}:
		if isTOMLArrayTableSlice(x) {
			return 1
		}
		return 0
	default:
		return 0
	}
}

func tomlIsEmptyForOmit(v interface{}) bool {
	switch x := v.(type) {
	case string:
		return x == ""
	case bool:
		return !x
	case []interface{}:
		// nil elements are dropped by the encoder
		for _, e := range x {
			if e != nil {
				return false
			}
		}
		return true
	default:
		return false
	}
}

func newTOMLInlineMap(x order.MapSlice) tomlInlineMap {
	m := tomlInlineMap{}
	for i, item := range x {
		if item.Key == "-" {
			continue
		}
		name := item.Key
		var opts []string
		if idx := strings.Index(name, ","); idx >= 0 {
			opts = strings.Split(name[idx+1:], ",")
			name = name[:idx]
		}
		eff := name
		if eff == "" {
			eff = tomlFieldName(i)
		}
		written := item.Val != nil
		if written {
			for _, o := range opts {
				if o == "omitempty" && tomlIsEmptyForOmit(item.Val) {
					written = false
					break
				}
			}
		}
		m.fields = append(m.fields, tomlInlineField{
			orig:    i,
			key:     eff,
			val:     tomlConvertInlineValue(item.Val),
			cat:     tomlInlineCategory(item.Val),
			written: written,
		})
	}
	return m
}

func tomlFormatKey(s string) string {
	bare := s != ""
	for _, r := range s {
		if !(r >= 'A' && r <= 'Z' || r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == '_' || r == '-') {
			bare = false
			break
		}
	}
	if bare {
		return s
	}
	b, err := toml.Marshal(s)
	if err != nil {
		return strconv.Quote(s)
	}
	return string(b)
}

func tomlMarshalInlineValue(v interface{}) (string, error) {
	switch x := v.(type) {
	case tomlInlineMap:
		b, err := x.MarshalTOML()
		return string(b), err
	case []interface{}:
		parts := make([]string, 0, len(x))
		for _, e := range x {
			s, err := tomlMarshalInlineValue(e)
			if err != nil {
				return "", err
			}
			parts = append(parts, s)
		}
		return "[" + strings.Join(parts, ", ") + "]", nil
	default:
		b, err := toml.Marshal(v)
		return string(b), err
	}
}

func (m tomlInlineMap) MarshalTOML() ([]byte, error) {
	var counts [2]int
	for _, f := range m.fields {
		counts[f.cat]++
	}
	var ordered []tomlInlineField
	for cat := 0; cat < 2; cat++ {
		for _, f := range m.fields {
			if f.written && f.cat == cat {
				ordered = append(ordered, f)
			}
		}
	}
	var buf bytes.Buffer
	buf.WriteByte('{')
	for _, f := range ordered {
		vs, err := tomlMarshalInlineValue(f.val)
		if err != nil {
			return nil, err
		}
		buf.WriteString(tomlFormatKey(f.key))
		buf.WriteString(" = ")
		buf.WriteString(vs)
		if f.orig != counts[f.cat]-1 {
			buf.WriteString(", ")
		}
	}
	buf.WriteByte('}')
	return buf.Bytes(), nil
}

