import pathlib
p=pathlib.Path('hcl.go'); s=p.read_text()
s=s.replace('''type scanCore struct {
	src []rune
	off int
}

func newScanCore(data []byte) *scanCore { return &scanCore{src: []rune(string(data))} }''','''type scanCore struct {
	src        []rune
	off        int
	lineStarts []int
}

func newScanCore(data []byte) *scanCore {
	src := []rune(string(data))
	starts := []int{0}
	for i, r := range src {
		if r == '\\n' {
			starts = append(starts, i+1)
		}
	}
	return &scanCore{src: src, lineStarts: starts}
}''')
s=s.replace('''func (s *scanCore) posAt(off int) hPos {
	line, col := 1, 1
	for i := 0; i < off && i < len(s.src); i++ {
		if s.src[i] == '\\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	if off > len(s.src) {
		col += off - len(s.src)
	}
	return hPos{line, col}
}''','''func (s *scanCore) posAt(off int) hPos {
	if off < 0 {
		off = 0
	}
	// largest line start <= off (for off==len after a trailing newline,
	// that start is len, giving col 1 on the next line)
	lo, hi := 0, len(s.lineStarts)-1
	for lo < hi {
		mid := (lo + hi + 1) / 2
		if s.lineStarts[mid] <= off {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	return hPos{lo + 1, off - s.lineStarts[lo] + 1}
}''')
p.write_text(s)
