package main

import (
	"fmt"
	"strconv"
	"strings"
)

// This pre-check rejects a few TOML 1.1-only constructs that newer
// TOML parsers accept but the reference (TOML 1.0) rejects. It is
// deliberately conservative: if it cannot understand the token
// stream, it reports nothing and the main parser's result stands.

type tvKind int

const (
	tvEOF tvKind = iota
	tvNewline
	tvBare
	tvString
	tvPunct
)

type tvTok struct {
	kind      tvKind
	text      string // bare/punct text
	strVal    string // decoded string (keys)
	basic     bool   // string was a basic (double-quoted) string
	badEscape byte   // 'x' or 'e' if a TOML 1.1 escape was used
	line      int
}

type tvLexer struct {
	src  []rune
	i    int
	line int
}

func (l *tvLexer) next() tvTok {
	for l.i < len(l.src) {
		ch := l.src[l.i]
		if ch == ' ' || ch == '\t' || ch == '\r' {
			l.i++
			continue
		}
		if ch == '#' {
			for l.i < len(l.src) && l.src[l.i] != '\n' {
				l.i++
			}
			continue
		}
		break
	}
	if l.i >= len(l.src) {
		return tvTok{kind: tvEOF, line: l.line}
	}
	ch := l.src[l.i]
	line := l.line
	switch {
	case ch == '\n':
		l.i++
		l.line++
		return tvTok{kind: tvNewline, line: line}
	case ch == '"' || ch == '\'':
		return l.lexString()
	case ch == '[' || ch == ']' || ch == '{' || ch == '}' || ch == '=' || ch == ',':
		l.i++
		return tvTok{kind: tvPunct, text: string(ch), line: line}
	default:
		start := l.i
		for l.i < len(l.src) {
			c := l.src[l.i]
			if c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '#' ||
				c == '[' || c == ']' || c == '{' || c == '}' || c == '=' || c == ',' ||
				c == '"' || c == '\'' {
				break
			}
			l.i++
		}
		if start == l.i {
			// Unknown char; consume it as a bare token to avoid looping.
			l.i++
		}
		return tvTok{kind: tvBare, text: string(l.src[start:l.i]), line: line}
	}
}

func (l *tvLexer) lexString() tvTok {
	quote := l.src[l.i]
	line := l.line
	basic := quote == '"'
	// triple quoted?
	triple := l.i+2 < len(l.src) && l.src[l.i+1] == quote && l.src[l.i+2] == quote
	var bad byte
	var content strings.Builder
	if triple {
		l.i += 3
		for l.i < len(l.src) {
			if l.src[l.i] == quote && l.i+2 < len(l.src) && l.src[l.i+1] == quote && l.src[l.i+2] == quote {
				l.i += 3
				// up to two extra quotes belong to the string/close
				for n := 0; n < 2 && l.i < len(l.src) && l.src[l.i] == quote; n++ {
					l.i++
				}
				break
			}
			c := l.src[l.i]
			if c == '\n' {
				l.line++
				content.WriteRune(c)
				l.i++
				continue
			}
			if basic && c == '\\' && l.i+1 < len(l.src) {
				nx := l.src[l.i+1]
				if (nx == 'x' || nx == 'e') && bad == 0 {
					bad = byte(nx)
				}
				content.WriteRune(c)
				content.WriteRune(nx)
				if nx == '\n' {
					l.line++
				}
				l.i += 2
				continue
			}
			content.WriteRune(c)
			l.i++
		}
		return tvTok{kind: tvString, basic: basic, badEscape: bad, strVal: content.String(), line: line}
	}
	// single line
	l.i++ // opening quote
	start := l.i - 1
	for l.i < len(l.src) {
		c := l.src[l.i]
		if c == quote {
			l.i++
			break
		}
		if c == '\n' {
			break
		}
		if basic && c == '\\' && l.i+1 < len(l.src) {
			nx := l.src[l.i+1]
			if (nx == 'x' || nx == 'e') && bad == 0 {
				bad = byte(nx)
			}
			l.i += 2
			continue
		}
		l.i++
	}
	raw := string(l.src[start:l.i])
	val := ""
	if basic {
		if uq, err := strconv.Unquote(raw); err == nil {
			val = uq
		} else if len(raw) >= 2 {
			val = raw[1 : len(raw)-1]
		}
	} else if len(raw) >= 2 {
		val = raw[1 : len(raw)-1]
	}
	return tvTok{kind: tvString, basic: basic, badEscape: bad, strVal: val, line: line}
}

type tvParser struct {
	toks []tvTok
	i    int
	bail bool
}

func (p *tvParser) cur() tvTok {
	if p.i < len(p.toks) {
		return p.toks[p.i]
	}
	return tvTok{kind: tvEOF}
}

func (p *tvParser) advance() tvTok {
	t := p.cur()
	p.i++
	return t
}

func (p *tvParser) skipNewlines() {
	for p.cur().kind == tvNewline {
		p.i++
	}
}

func tvJoin(path []string) string { return strings.Join(path, ".") }

func tvErr(line int, lastKey, msg string) error {
	return fmt.Errorf("toml: line %d (last key %q): %s", line, lastKey, msg)
}

// parseKeyPath parses a dotted key. Returns segments or bails.
func (p *tvParser) parseKeyPath() []string {
	var segs []string
	for {
		t := p.cur()
		switch t.kind {
		case tvString:
			if t.badEscape != 0 {
				p.bail = true
				return segs
			}
			segs = append(segs, t.strVal)
			p.advance()
		case tvBare:
			text := t.text
			p.advance()
			parts := strings.Split(text, ".")
			for idx, part := range parts {
				if part == "" {
					if idx == 0 && len(segs) > 0 {
						continue // leading dot after a quoted segment
					}
					// trailing dot: next segment follows in next token
					continue
				}
				segs = append(segs, part)
			}
			if strings.HasSuffix(text, ".") {
				continue
			}
		default:
			if len(segs) == 0 {
				p.bail = true
			}
			return segs
		}
		// After a segment, a following bare token starting with '.'
		// continues the path.
		if nt := p.cur(); nt.kind == tvBare && strings.HasPrefix(nt.text, ".") {
			continue
		}
		return segs
	}
}

func missingSeconds(tok string) bool {
	isDigit := func(c byte) bool { return c >= '0' && c <= '9' }
	checkTime := func(s string) bool {
		// HH:MM without :SS, optionally fractional (invalid anyway)
		if len(s) < 5 || !isDigit(s[0]) || !isDigit(s[1]) || s[2] != ':' || !isDigit(s[3]) || !isDigit(s[4]) {
			return false
		}
		if len(s) == 5 {
			return true
		}
		// fractional directly after minutes, or offset/Z after minutes
		c := s[5]
		return c == '.' || c == 'Z' || c == 'z' || c == '+' || c == '-'
	}
	if checkTime(tok) {
		return true
	}
	// datetime: find T or space separator
	for i := 0; i < len(tok); i++ {
		if tok[i] == 'T' || tok[i] == 't' || tok[i] == ' ' {
			if i == 10 { // YYYY-MM-DD
				return checkTime(tok[i+1:])
			}
			return false
		}
	}
	return false
}

// inline frame
type tvFrame struct {
	contextPath []string
	lastKey     string
}

func (p *tvParser) parseValue(fullPath []string, errKey string) error {
	t := p.cur()
	switch t.kind {
	case tvString:
		p.advance()
		if t.badEscape != 0 {
			return tvErr(t.line, errKey, fmt.Sprintf("invalid escape in string '\\%c'", t.badEscape))
		}
		return nil
	case tvBare:
		text := t.text
		line := t.line
		p.advance()
		// space-separated datetime: date token followed by time token
		if len(text) == 10 && text[4] == '-' && text[7] == '-' {
			if nt := p.cur(); nt.kind == tvBare && nt.line == line && len(nt.text) >= 5 && nt.text[2] == ':' {
				text = text + " " + nt.text
				p.advance()
			}
		}
		if missingSeconds(text) {
			return tvErr(line, errKey, fmt.Sprintf("Invalid TOML Datetime: %q.", text))
		}
		return nil
	case tvPunct:
		if t.text == "[" {
			return p.parseArray(fullPath, errKey)
		}
		if t.text == "{" {
			return p.parseInline(fullPath)
		}
		p.bail = true
		return nil
	default:
		p.bail = true
		return nil
	}
}

func (p *tvParser) parseArray(fullPath []string, errKey string) error {
	p.advance() // '['
	for {
		for p.cur().kind == tvNewline || (p.cur().kind == tvPunct && p.cur().text == ",") {
			p.advance()
		}
		if p.cur().kind == tvPunct && p.cur().text == "]" {
			p.advance()
			return nil
		}
		if p.cur().kind == tvEOF {
			p.bail = true
			return nil
		}
		if err := p.parseValue(fullPath, errKey); err != nil {
			return err
		}
		if p.bail {
			return nil
		}
	}
}

func (p *tvParser) parseInline(contextPath []string) error {
	p.advance() // '{'
	frame := &tvFrame{contextPath: contextPath, lastKey: tvJoin(contextPath)}
	// state: 0 after open, 1 after value, 2 after comma
	state := 0
	for {
		t := p.cur()
		if t.kind == tvEOF {
			p.bail = true
			return nil
		}
		if t.kind == tvNewline {
			return tvErr(t.line, frame.lastKey, "newlines not allowed within inline tables")
		}
		if t.kind == tvPunct && t.text == "}" {
			if state == 2 {
				return tvErr(t.line, frame.lastKey, "trailing comma not allowed in inline tables")
			}
			p.advance()
			return nil
		}
		if t.kind == tvPunct && t.text == "," {
			if state != 1 {
				p.bail = true
				return nil
			}
			state = 2
			p.advance()
			continue
		}
		if state == 1 {
			// expected comma or }
			p.bail = true
			return nil
		}
		// parse an assignment within the inline table
		if err := p.parseInlineAssignment(frame); err != nil {
			return err
		}
		if p.bail {
			return nil
		}
		state = 1
	}
}

func (p *tvParser) parseInlineAssignment(frame *tvFrame) error {
	segs := p.parseKeyPath()
	if p.bail || len(segs) == 0 {
		p.bail = true
		return nil
	}
	t := p.cur()
	if t.kind == tvNewline {
		return tvErr(t.line+1, frame.lastKey, "expected '.' or '=', but got '\\n' instead")
	}
	if !(t.kind == tvPunct && t.text == "=") {
		p.bail = true
		return nil
	}
	p.advance()
	errKey := tvJoin(append(append([]string{}, frame.contextPath...), segs[len(segs)-1]))
	fullPath := append(append([]string{}, frame.contextPath...), segs...)
	t = p.cur()
	if t.kind == tvNewline {
		return tvErr(t.line+1, errKey, "expected value but found '\\n' instead")
	}
	if err := p.parseValue(fullPath, errKey); err != nil {
		return err
	}
	frame.lastKey = errKey
	return nil
}

func (p *tvParser) parseRootAssignment(tablePath []string) error {
	segs := p.parseKeyPath()
	if p.bail || len(segs) == 0 {
		p.bail = true
		return nil
	}
	t := p.cur()
	if !(t.kind == tvPunct && t.text == "=") {
		p.bail = true
		return nil
	}
	p.advance()
	fullPath := append(append([]string{}, tablePath...), segs...)
	return p.parseValue(fullPath, tvJoin(fullPath))
}

func precheckTOML10(data []byte) error {
	lex := &tvLexer{src: []rune(string(data)), line: 1}
	var toks []tvTok
	for {
		t := lex.next()
		toks = append(toks, t)
		if t.kind == tvEOF {
			break
		}
	}
	p := &tvParser{toks: toks}
	var tablePath []string
	for {
		p.skipNewlines()
		if p.bail || p.cur().kind == tvEOF {
			return nil
		}
		t := p.cur()
		if t.kind == tvPunct && t.text == "[" {
			// table header
			p.advance()
			isArray := false
			if p.cur().kind == tvPunct && p.cur().text == "[" {
				isArray = true
				p.advance()
			}
			segs := p.parseKeyPath()
			if p.bail || len(segs) == 0 {
				return nil
			}
			if !(p.cur().kind == tvPunct && p.cur().text == "]") {
				return nil
			}
			p.advance()
			if isArray {
				if !(p.cur().kind == tvPunct && p.cur().text == "]") {
					return nil
				}
				p.advance()
			}
			tablePath = segs
			continue
		}
		if err := p.parseRootAssignment(tablePath); err != nil {
			return err
		}
		if p.bail {
			return nil
		}
	}
}
EOF
