}

// parseKeyPath parses a dotted key. Returns segments or bails.
func (p *tvParser) parseKeyPath() []string {
	var segs []string
	for {
		t := p.cur()
		switch t.kind {
		case tvString:
			if t.badEscape != 0 {
				p.bail = true
				return segs
			}
			segs = append(segs, t.strVal)
			p.advance()
		case tvBare:
			text := t.text
			p.advance()
			parts := strings.Split(text, ".")
			for idx, part := range parts {
				if part == "" {
					if idx == 0 && len(segs) > 0 {
						continue // leading dot after a quoted segment
					}
					// trailing dot: next segment follows in next token
					continue
				}
				segs = append(segs, part)
			}
			if strings.HasSuffix(text, ".") {
				continue
			}
