		p.advance()
		// space-separated datetime: date token followed by time token
		if len(text) == 10 && text[4] == '-' && text[7] == '-' {
			if nt := p.cur(); nt.kind == tvBare && nt.line == line && len(nt.text) >= 5 && nt.text[2] == ':' {
				text = text + " " + nt.text
				p.advance()
			}
		}
		if missingSeconds(text) {
			return tvErr(line, errKey, fmt.Sprintf("Invalid TOML Datetime: %q.", text))
		}
		return nil
	case tvPunct:
		if t.text == "[" {
			return p.parseArray(fullPath, errKey)
		}
		if t.text == "{" {
			return p.parseInline(fullPath)
		}
		p.bail = true
		return nil
	default:
		p.bail = true
		return nil
	}
}

func (p *tvParser) parseArray(fullPath []string, errKey string) error {
	p.advance() // '['
	for {
		for p.cur().kind == tvNewline || (p.cur().kind == tvPunct && p.cur().text == ",") {
			p.advance()
		}
		if p.cur().kind == tvPunct && p.cur().text == "]" {
			p.advance()
			return nil
		}
		if p.cur().kind == tvEOF {
			p.bail = true
			return nil
		}
		if err := p.parseValue(fullPath, errKey); err != nil {
			return err
		}
		if p.bail {
			return nil
		}
	}
}

func (p *tvParser) parseInline(contextPath []string) error {
	p.advance() // '{'
	frame := &tvFrame{contextPath: contextPath, lastKey: tvJoin(contextPath)}
	// state: 0 after open, 1 after value, 2 after comma
	state := 0
	for {
		t := p.cur()
		if t.kind == tvEOF {
			p.bail = true
			return nil
		}
		if t.kind == tvNewline {
			return tvErr(t.line, frame.lastKey, "newlines not allowed within inline tables")
		}
		if t.kind == tvPunct && t.text == "}" {
			if state == 2 {
				return tvErr(t.line, frame.lastKey, "trailing comma not allowed in inline tables")
			}
			p.advance()
			return nil
		}
		if t.kind == tvPunct && t.text == "," {
			if state != 1 {
				p.bail = true
				return nil
			}
			state = 2
			p.advance()
			continue
		}
		if state == 1 {
			// expected comma or }
			p.bail = true
			return nil
		}
		// parse an assignment within the inline table
		if err := p.parseInlineAssignment(frame); err != nil {
			return err
		}
		if p.bail {
			return nil
		}
		state = 1
	}
}

func (p *tvParser) parseInlineAssignment(frame *tvFrame) error {
	segs := p.parseKeyPath()
	if p.bail || len(segs) == 0 {
		p.bail = true
		return nil
	}
	t := p.cur()
	if t.kind == tvNewline {
		return tvErr(t.line+1, frame.lastKey, "expected '.' or '=', but got '\\n' instead")
	}
	if !(t.kind == tvPunct && t.text == "=") {
		p.bail = true
		return nil
	}
	p.advance()
	errKey := tvJoin(append(append([]string{}, frame.contextPath...), segs[len(segs)-1]))
	fullPath := append(append([]string{}, frame.contextPath...), segs...)
	t = p.cur()
	if t.kind == tvNewline {
		return tvErr(t.line+1, errKey, "expected value but found '\\n' instead")
	}
	if err := p.parseValue(fullPath, errKey); err != nil {
		return err
	}
	frame.lastKey = errKey
	return nil
}

func (p *tvParser) parseRootAssignment(tablePath []string) error {
	segs := p.parseKeyPath()
	if p.bail || len(segs) == 0 {
		p.bail = true
		return nil
	}
	t := p.cur()
	if !(t.kind == tvPunct && t.text == "=") {
		p.bail = true
		return nil
	}
	p.advance()
	fullPath := append(append([]string{}, tablePath...), segs...)
	return p.parseValue(fullPath, tvJoin(fullPath))
}

func precheckTOML10(data []byte) error {
	lex := &tvLexer{src: []rune(string(data)), line: 1}
	var toks []tvTok
	for {
		t := lex.next()
		toks = append(toks, t)
		if t.kind == tvEOF {
			break
		}
	}
	p := &tvParser{toks: toks}
	var tablePath []string
	for {
		p.skipNewlines()
		if p.bail || p.cur().kind == tvEOF {
			return nil
		}
		t := p.cur()
		if t.kind == tvPunct && t.text == "[" {
			// table header
			p.advance()
			isArray := false
			if p.cur().kind == tvPunct && p.cur().text == "[" {
				isArray = true
				p.advance()
			}
			segs := p.parseKeyPath()
			if p.bail || len(segs) == 0 {
				return nil
			}
			if !(p.cur().kind == tvPunct && p.cur().text == "]") {
				return nil
			}
			p.advance()
			if isArray {
				if !(p.cur().kind == tvPunct && p.cur().text == "]") {
					return nil
				}
				p.advance()
			}
			tablePath = segs
			continue
		}
		if err := p.parseRootAssignment(tablePath); err != nil {
			return err
		}
		if p.bail {
			return nil
		}
	}
}
