		return s, len(s), false
	}
	return s, len(s), true
}

func tomlBracketBalance(s string) (int, bool) {
	inSingle, inDouble := false, false
	depth := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inDouble {
			if c == '\\' {
				i++
				continue
			}
			if c == '"' {
				inDouble = false
			}
			continue
		}
