			}
			segs = append(segs, seg)
			i = j + 1
		} else {
			j := i
			for j < len(s) {
				c := s[j]
				if c == '.' || c == '=' || c == ' ' || c == '\t' || c == ']' || c == '[' {
					break
				}
				j++
