			end := strings.LastIndex(content, "]")
			if start < 0 || end <= start {
				return nil, false
			}
			inner := content[start+1 : end]
			segs, pos, ok := parseTOMLKeyAt(inner, 0)
			if !ok || len(segs) == 0 {
				return nil, false
			}
			rest := strings.TrimSpace(inner[pos:])
			if rest != "" {
				return nil, false
			}
			tablePath = segs
			continue
		}
		// assignment line
		indent := 0
		for indent < len(line) && (line[indent] == ' ' || line[indent] == '\t') {
			indent++
		}
		segs, pos, ok := parseTOMLKeyAt(line, indent)
		if !ok || len(segs) == 0 {
			return nil, false
		}
		for pos < len(line) && (line[pos] == ' ' || line[pos] == '\t') {
			pos++
		}
		if pos >= len(line) || line[pos] != '=' {
			return nil, false
		}
		valStart := pos + 1
		// comment / bracket checks on value
		valAndRest := line[valStart:]
		_, commentAt, okc := stripTOMLComment(valAndRest)
		if !okc {
			return nil, false
		}
		valEnd := valStart + commentAt
		valueText := line[valStart:valEnd]
		if bal, okb := tomlBracketBalance(valueText); !okb || bal != 0 {
			return nil, false
		}
		fullSegs := append(append([]string{}, tablePath...), segs...)
		var kb strings.Builder
		for _, s := range fullSegs {
			kb.WriteString(strconv.Quote(s))
			kb.WriteByte(0)
		}
		fullKey := kb.String()
		a := &dupAssign{lineIdx: idx, fullKey: fullKey, valStart: valStart, valEnd: valEnd,
			isArray: strings.HasPrefix(strings.TrimSpace(valueText), "[")}
		assigns = append(assigns, a)
		if _, seen := groups[fullKey]; !seen {
			groupOrder = append(groupOrder, fullKey)
		}
		groups[fullKey] = append(groups[fullKey], a)
	}
	_ = assigns

	hasDup := false
	for _, key := range groupOrder {
		g := groups[key]
		if len(g) < 2 {
			continue
