{"command":"cat > tomldup.go <<'EOF'
package main

import (
	"strconv"
	"strings"
)

// rewriteDuplicateArrayAssignments handles a narrow case where the
// older TOML parser in the reference permits redefining a key when
// an array value is involved (the last assignment wins), while the
// newer parser rejects all duplicate keys. It only rewrites simple
// single-line assignments; anything more complex is left untouched.

type dupAssign struct {
	lineIdx  int
	fullKey  string
	valStart int
	valEnd   int
	isArray  bool
}

func stripTOMLComment(s string) (string, int, bool) {
	inSingle, inDouble := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inDouble {
			if c == '\\' {
				i++
				continue
			}
			if c == '"' {
				inDouble = false
			}
			continue
		}
		if inSingle {
			if c == '\'' {
				inSingle = false
			}
			continue
		}
		switch c {
		case '"':
			inDouble = true
		case '\'':
			inSingle = true
		case '#':
			return s[:i], i, true
		}
	}
	if inSingle || inDouble {
		return s, len(s), false
	}
	return s, len(s), true
}

func tomlBracketBalance(s string) (int, bool) {
	inSingle, inDouble := false, false
	depth := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inDouble {
			if c == '\\' {
				i++
				continue
			}
			if c == '"' {
				inDouble = false
			}
			continue
		}
		if inSingle {
			if c == '\'' {
				inSingle = false
			}
			continue
		}
		switch c {
		case '"':
			inDouble = true
		case '\'':
			inSingle = true
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		}
	}
	return depth, !inSingle && !inDouble
}

// parseTOMLKeyAt parses a dotted key at byte offset in s.
// Returns segments and the offset just after the key.
func parseTOMLKeyAt(s string, i int) ([]string, int, bool) {
	var segs []string
	for {
		for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
			i++
		}
		if i >= len(s) {
			return nil, i, false
		}
		if s[i] == '"' || s[i] == '\'' {
			q := s[i]
			j := i + 1
			for j < len(s) {
				if q == '"' && s[j] == '\\' {
					j += 2
					continue
				}
				if s[j] == q {
					break
				}
				j++
			}
			if j >= len(s) {
				return nil, i, false
			}
			raw := s[i : j+1]
			var seg string
			if q == '"' {
				uq, err := strconv.Unquote(raw)
				if err != nil {
					return nil, i, false
				}
				seg = uq
			} else {
				seg = raw[1 : len(raw)-1]
			}
			segs = append(segs, seg)
			i = j + 1
		} else {
			j := i
			for j < len(s) {
				c := s[j]
				if c == '.' || c == '=' || c == ' ' || c == '\t' || c == ']' || c == '[' {
					break
				}
				j++
			}
			if j == i {
				return nil, i, false
			}
			segs = append(segs, s[i:j])
			i = j
		}
		for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
			i++
		}
		if i < len(s) && s[i] == '.' {
			i++
			continue
		}
		return segs, i, true
	}
}

func rewriteDuplicateArrayAssignments(data []byte) ([]byte, bool) {
	text := string(data)
	if strings.Contains(text, "\r") || strings.Contains(text, "\"\"\"") || strings.Contains(text, "'''") {
		return nil, false
	}
	lines := strings.SplitAfter(text, "\n")
	var tablePath []string
	var assigns []*dupAssign
	groups := map[string][]*dupAssign{}
	var groupOrder []string

	for idx, rawLine := range lines {
		line := strings.TrimSuffix(rawLine, "\n")
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		if strings.HasPrefix(trimmed, "[[") {
			return nil, false
		}
		if strings.HasPrefix(trimmed, "[") {
			// table header: find closing bracket outside strings
			content, _, okc := stripTOMLComment(line)
			if !okc {
				return nil, false
			}
			start := strings.Index(content, "[")
			// find matching ']' (last ] outside strings, approximated by lastIndex)
			end := strings.LastIndex(content, "]")
			if start < 0 || end <= start {
				return nil, false
			}
			inner := content[start+1 : end]
			segs, pos, ok := parseTOMLKeyAt(inner, 0)
			if !ok || len(segs) == 0 {
				return nil, false
			}
			rest := strings.TrimSpace(inner[pos:])
			if rest != "" {
				return nil, false
			}
			tablePath = segs
			continue
		}
		// assignment line
		indent := 0
		for indent < len(line) && (line[indent] == ' ' || line[indent] == '\t') {
			indent++
		}
		segs, pos, ok := parseTOMLKeyAt(line, indent)
		if !ok || len(segs) == 0 {
			return nil, false
		}
		for pos < len(line) && (line[pos] == ' ' || line[pos] == '\t') {
			pos++
		}
		if pos >= len(line) || line[pos] != '=' {
			return nil, false
		}
		valStart := pos + 1
		// comment / bracket checks on value
		valAndRest := line[valStart:]
		_, commentAt, okc := stripTOMLComment(valAndRest)
		if !okc {
			return nil, false
		}
		valEnd := valStart + commentAt
		valueText := line[valStart:valEnd]
		if bal, okb := tomlBracketBalance(valueText); !okb || bal != 0 {
			return nil, false
		}
		fullSegs := append(append([]string{}, tablePath...), segs...)
		var kb strings.Builder
		for _, s := range fullSegs {
			kb.WriteString(strconv.Quote(s))
			kb.WriteByte(0)
		}
		fullKey := kb.String()
		a := &dupAssign{lineIdx: idx, fullKey: fullKey, valStart: valStart, valEnd: valEnd,
			isArray: strings.HasPrefix(strings.TrimSpace(valueText), "[")}
		assigns = append(assigns, a)
		if _, seen := groups[fullKey]; !seen {
			groupOrder = append(groupOrder, fullKey)
		}
		groups[fullKey] = append(groups[fullKey], a)
	}
	_ = assigns

	hasDup := false
	for _, key := range groupOrder {
		g := groups[key]
		if len(g) < 2 {
			continue
		}
		hasDup = true
		for i := 1; i < len(g); i++ {
			if !g[i].isArray && !g[i-1].isArray {
				return nil, false
			}
		}
	}
	if !hasDup {
		return nil, false
	}
	newLines := append([]string{}, lines...)
	for _, key := range groupOrder {
		g := groups[key]
		if len(g) < 2 {
			continue
		}
		first, last := g[0], g[len(g)-1]
		firstLine := strings.TrimSuffix(newLines[first.lineIdx], "\n")
		lastLine := strings.TrimSuffix(lines[last.lineIdx], "\n")
		lastValue := lastLine[last.valStart:last.valEnd]
		rebuilt := firstLine[:first.valStart] + lastValue + firstLine[first.valEnd:]
		if strings.HasSuffix(newLines[first.lineIdx], "\n") {
			rebuilt += "\n"
		}
		newLines[first.lineIdx] = rebuilt
		for _, a := range g[1:] {
			if strings.HasSuffix(newLines[a.lineIdx], "\n") {
				newLines[a.lineIdx] = "\n"
			} else {
				newLines[a.lineIdx] = ""
			}
		}
	}
	return []byte(strings.Join(newLines, "")), true
}
